import json, re, html
from pathlib import Path
sources=json.loads(Path('source.json').read_text())
by={x['number']:x for x in sources}
answers={}
def plain(xml):
    return re.sub(r'\s+',' ',html.unescape(re.sub(r'<[^>]+>',' ',xml or ''))).strip()
def base(n):
    return {k:by[n][k] for k in ('code_id','source_id','source_sha256','number')}
def impact(c,a,s,b,e=None):
    return {'version':1,'classification':c,'assessment':a,'scope_limitations':s,'new_burdens_review':b,'effects':e or []}
def retained(n,reason,notes,assessment,scope,burdens,benefit=None):
    a=base(n)
    a.update(proposed_xml=None,reason=reason,review_notes=notes,status='retained_unchanged',classification='retained_necessary',substantive_impact=impact('retained_necessary',assessment,scope,burdens))
    if benefit:a['benefit_review']=benefit
    answers[n]=a

def effect(n,kind,mid,description,before,after,unit,pop,transition,replacement,sq,pq):
    return dict(kind=kind,measure_id=mid,description=description,before=before,after=after,unit=unit,affected_population=pop,conditions_and_transition=transition,replacement_or_new_burdens=replacement,source_quote=sq,proposed_quote=pq)
def rewrite(n,xml,reason,notes,c,assessment,scope,burdens,effects,removed=None,full=None):
    a=base(n)
    a.update(proposed_xml=xml,reason=reason,review_notes=notes,status='rewrite_draft',classification=c,substantive_impact=impact(c,assessment,scope,burdens,effects))
    if removed:
        a.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
    if full:
        a.update(change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope=full)
    answers[n]=a

